/**
 * Assign a Category to a Grouping (or clear it back to Uncategorized).
 *
 * The spending-hierarchy editor's core mutation: a category with no
 * `group_id` falls into the report's Uncategorized bucket, so this is how a
 * custom or renamed category gets pulled into a real Grouping without SQL.
 * Pass `null` to unassign.
 */
async assignCategoryToGroup(categoryId: string, groupId: string | null): Promise<void> {
	if (!categoryId) {
		throw new Error('Category ID is required');
	}

	const { error } = await this.supabase
		.from('categories')
		.update({ group_id: groupId, updated_at: new Date().toISOString() })
		.eq('id', categoryId);

	if (error) {
		throw new Error(error.message);
	}
}

/**
 * Move a Grouping to a different Area of Importance.
 *
 * Importance attaches to the Grouping (not the category), so re-parenting a
 * Grouping re-buckets all of its categories in the report at once.
 */
async moveGroupToImportance(groupId: string, importanceAreaId: string): Promise<void> {
	if (!groupId) {
		throw new Error('Group ID is required');
	}
	if (!importanceAreaId) {
		throw new Error('Importance area ID is required');
	}

	const { error } = await this.supabase
		.from('category_groups')
		.update({ importance_area_id: importanceAreaId, updated_at: new Date().toISOString() })
		.eq('id', groupId);

	if (error) {
		throw new Error(error.message);
	}
}

/**
 * Create default categories for a new family
 *
 * @param familyId - Family ID to create categories for
 *
 * Specification: #{#exp3a} Requirements 2 & 3
 */
async createDefaultCategories(familyId: string): Promise<void> {
	if (!familyId) {
		throw new Error('Family ID is required');
	}

	// Only create if family has no categories
	const existing = await this.getFamilyCategories(familyId);
	if (existing.length > 0) {
		return; // Family already has categories
	}

	// Insert default categories directly using the DEFAULT_CATEGORIES constant
	// This ensures we always use the latest category list
	const categoriesToInsert = DEFAULT_CATEGORIES.map((cat) => ({
		family_id: familyId,
		name: cat.name,
		color: cat.color
	}));

	const { error } = await this.supabase.from('categories').insert(categoriesToInsert);

	// Ignore unique constraint violations (23505) - categories already exist
	if (error && error.code !== '23505') {
		throw new Error(error.message);
	}
}

/**
 * Create a new custom category
 *
 * @param familyId - Family ID
 * @param name - Category name
 * @param color - Optional hex color code (#RRGGBB)
 * @param groupId - Optional Grouping to file the new category under (spending
 *   hierarchy). Omit/null leaves it Uncategorized.
 * @returns Created category
 *
 * Specification: #{#exp3a} Requirements 4, 7, 8
 */
async createCategory(
	familyId: string,
	name: string,
	color?: string,
	groupId?: string | null
): Promise<Category> {
	// Validation
	if (!familyId) {
		throw new Error('Family ID is required');
	}

	if (!name || name.trim() === '') {
		throw new Error('Category name is required');
	}

	if (name.length > 100) {
		throw new Error('Category name must be 100 characters or less');
	}

	// Validate color format if provided
	if (color !== undefined && color !== null && color !== '') {
		if (!this.isValidHexColor(color)) {
			throw new Error('Invalid color format. Use hex format: #RRGGBB');
		}
	}

	// Insert category. group_id is only set when a Grouping was chosen, so an
	// unassigned new category stays Uncategorized (group_id NULL).
	const { data, error } = await this.supabase
		.from('categories')
		.insert({
			family_id: familyId,
			name: name.trim(),
			color: color || null,
			group_id: groupId || null
		})
		.select()
		.single();

	if (error) {
		// Handle unique constraint violation
		if (error.code === '23505') {
			throw new Error('A category with this name already exists in this family');
		}
		throw new Error(error.message);
	}

	return data;
}

