1	<script lang="ts">
2		/**
3		 * Spending hierarchy editor
4		 *
5		 * Lets the family maintainer restructure the spending hierarchy without SQL:
6		 *   - assign a Category to a Grouping (or back to Uncategorized)
7		 *   - move a Grouping to a different Area of Importance
8		 *
9		 * The report attaches Importance to the Grouping, so moving a Grouping
10		 * re-buckets all its Categories at once. Categories with no Grouping land in
11		 * the "Unassigned" bucket up top — the whole reason this editor exists (the
12		 * seed maps categories by name, so custom/renamed ones start unassigned).
13		 *
14		 * Tree shaping is the pure `buildHierarchyTree`; this page loads the three
15		 * hierarchy tables, renders the tree, and calls CategoryService mutations,
16		 * reloading after each. Design: docs/plans/2026-07-09-spending-report-design.md
17		 */
18	
19		import { onMount } from 'svelte';
20		import { resolve } from '$app/paths';
21		import { supabase } from '$lib/supabaseClient';
22		import { CategoryService } from '$lib/services/CategoryService';
23		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
24		import { buildHierarchyTree, type HierarchyTree } from '$lib/utils/hierarchyTree';
25		import HierarchyEditor from '$lib/components/HierarchyEditor.svelte';
26		import type { ImportanceArea } from '$lib/types/Hierarchy';
27		import type { Session } from '@supabase/supabase-js';
28	
29		let session: Session | null = $state(null);
30		let familyId: string | null = $state(null);
31		let loading = $state(true);
32		let saving = $state(false);
33		let error: string | null = $state(null);
34		let tree = $state<HierarchyTree | null>(null);
35		let importanceAreas = $state<ImportanceArea[]>([]);
36	
37		const service = new CategoryService(supabase);
38	
39		onMount(async () => {
40			const { data } = await supabase.auth.getSession();
41			session = data.session;
42			if (!session) {
43				loading = false;
44				return;
45			}
46	
47			familyId = await getDefaultFamilyId();
48			if (!familyId) {
49				error = 'No family found. Please contact support.';
50				loading = false;
51				return;
52			}
53	
54			await load();
55		});
56	
57		async function load() {
58			if (!familyId) return;
59	
60			try {
61				loading = true;
62				error = null;
63	
64				// Self-seed the default hierarchy if this family has none yet (mirrors
65				// the /spending report's lazy-init), so the editor is never empty.
66				let areas = await service.getFamilyImportanceAreas(familyId);
67				if (areas.length === 0) {
68					await service.createDefaultHierarchy(familyId);
69					areas = await service.getFamilyImportanceAreas(familyId);
70				}
71	
72				const [groups, categories] = await Promise.all([
73					service.getFamilyGroups(familyId),
74					service.getFamilyCategories(familyId)
75				]);
76	
77				importanceAreas = areas;
78				tree = buildHierarchyTree(areas, groups, categories);
79			} catch (err) {
80				console.error('Error loading hierarchy:', err);
81				error = err instanceof Error ? err.message : 'Failed to load the hierarchy';
82			} finally {
83				loading = false;
84			}
85		}
86	
87		/** Run a mutation, surface any error in the UI, then reload the tree. */
88		async function mutate(action: () => Promise<void>) {
89			try {
90				saving = true;
91				error = null;
92				await action();
93				await load();
94			} catch (err) {
95				console.error('Error saving hierarchy change:', err);
96				error = err instanceof Error ? err.message : 'Failed to save the change';
97			} finally {
98				saving = false;
99			}
100		}
101	
102		function assignCategory(categoryId: string, groupId: string | null) {
103			mutate(() => service.assignCategoryToGroup(categoryId, groupId));
104		}
105	
106		function moveGroup(groupId: string, importanceAreaId: string) {
107			if (!importanceAreaId) return;
108			mutate(() => service.moveGroupToImportance(groupId, importanceAreaId));
109		}
110	
111		const hasHierarchy = $derived(tree !== null && tree.importances.length > 0);
112	</script>
