import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { CategoryService } from './CategoryService';
import {
	createMockSupabaseClient,
	getMockQuery,
	type MockQueryBuilder
} from '$lib/tests/fixtures/supabaseMock';

/**
 * CategoryService Test Suite
 *
 * Tests for Family Category Management
 *
 * Requirements:
 * 1. Categories must be scoped to families (family_id foreign key)
 * 2. New families must receive a default set of common categories on creation
 * 3. Default categories must include the full list defined in CategoryService
 * 4. Family members must be able to create custom categories
 * 5. Family members must be able to rename existing categories (affects all expenses in category)
 * 6. Family members must be able to delete categories (with confirmation if expenses exist in category)
 * 7. Category names must be unique per family (case-insensitive)
 * 8. Categories must support optional color coding for visual distinction
 */

describe('CategoryService - User Category Management', () => {
	let mockSupabase: SupabaseClient;

	beforeEach(() => {
		mockSupabase = createMockSupabaseClient();
	});

