1	import { vi, type Mock } from 'vitest';
2	import type { SupabaseClient } from '@supabase/supabase-js';
3	
4	/**
5	 * Shared chainable Supabase client mock for DI-style service specs.
6	 *
7	 * The services under test (`ExpenseService`, `CategoryService`, and any other
8	 * constructor-injected service) take a `SupabaseClient` and issue PostgREST-style
9	 * chains — `from(table).select(...).eq(...).single()` / `.upsert(...)` / a bare
10	 * `await from(table)...`. This builder returns a single shared query stub per client
11	 * where every filter/modifier method returns `this`, so the chain is order-agnostic
12	 * and a test only has to set `data` / `error` (or override a terminal like `single`)
13	 * for the path it exercises.
14	 *
15	 * This is the one canonical builder — do NOT hand-roll another `createMockSupabaseClient`
16	 * in a spec. It is a superset of the two shapes that previously diverged
17	 * (`ExpenseService`'s and `CategoryService`'s), so both suites consume it unchanged.
18	 *
19	 * NOT for the `ReceiptService.*` / reconciliation specs: those `vi.mock('$lib/supabaseClient')`
20	 * and wire explicit per-call chains that return *different* results across a sequence
21	 * (fetch original → insert split → update → delete). A single shared `mockReturnThis`
22	 * stub can't express that, and `vi.mock` is hoisted per-module so its preamble can't be
23	 * import-shared anyway. Leave those as-is.
24	 */
25	export interface MockQueryBuilder {
26		data: unknown;
27		error: { message: string; code?: string } | null;
28		select: Mock;
29		eq: Mock;
30		gte: Mock;
31		lte: Mock;
32		ilike: Mock;
33		in: Mock;
34		order: Mock;
35		returns: Mock;
36		insert: Mock;
37		update: Mock;
38		delete: Mock;
39		upsert: Mock;
40		single: Mock;
41		then: Mock;
42	}
43	
44	/** Retrieve the query stub behind `client.from(table)` with its mock surface exposed. */
45	export function getMockQuery(client: SupabaseClient, table: string): MockQueryBuilder {
46		return client.from(table) as unknown as MockQueryBuilder;
47	}
48	
49	/** Replace what the mocked `client.from()` returns for subsequent calls. */
50	export function setFromResult(client: SupabaseClient, builder: object): void {
51		(client.from as unknown as Mock).mockReturnValue(builder);
52	}
53	
54	/**
55	 * Build a chainable Supabase client mock with a single shared query stub.
56	 *
57	 * `single()` and the thenable `then()` both read the stub's live `data` / `error`
58	 * (so a test sets `getMockQuery(client, table).data = …` once); `single()` also unwraps
59	 * a non-empty array to its first element, mirroring PostgREST's single-row semantics.
60	 */
61	export function createMockSupabaseClient(): SupabaseClient {
62		const mockQuery = {
63			data: null as unknown,
64			error: null as { message: string; code?: string } | null,
65			select: vi.fn().mockReturnThis(),
66			eq: vi.fn().mockReturnThis(),
67			gte: vi.fn().mockReturnThis(),
68			lte: vi.fn().mockReturnThis(),
69			ilike: vi.fn().mockReturnThis(),
70			in: vi.fn().mockReturnThis(),
71			order: vi.fn().mockReturnThis(),
72			returns: vi.fn().mockReturnThis(),
73			insert: vi.fn().mockReturnThis(),
74			update: vi.fn().mockReturnThis(),
75			delete: vi.fn().mockReturnThis(),
76			upsert: vi.fn().mockResolvedValue({ data: null, error: null }),
77			single: vi.fn(function (this: MockQueryBuilder) {
78				// PostgREST single-row: unwrap a non-empty array to its first element.
79				if (Array.isArray(this.data) && this.data.length > 0) {
80					return Promise.resolve({ data: this.data[0], error: this.error });
81				}
82				return Promise.resolve({ data: this.data, error: this.error });
83			}),
84			then: vi.fn(function (this: MockQueryBuilder, resolve: (value: unknown) => unknown) {
85				// Make the query object awaitable for `const { data, error } = await from()...`.
86				return resolve({ data: this.data, error: this.error });
87			})
88		};
89	
90		return {
91			from: vi.fn().mockReturnValue(mockQuery),
92			rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
93			auth: {
94				getUser: vi.fn().mockResolvedValue({ data: { user: { id: 'test-user-id' } }, error: null }),
95				getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user-id' } } } })
96			}
97		} as unknown as SupabaseClient;
98	}
99

