	then: Mock;
}

/** Retrieve the query stub behind `client.from(table)` with its mock surface exposed. */
export function getMockQuery(client: SupabaseClient, table: string): MockQueryBuilder {
	return client.from(table) as unknown as MockQueryBuilder;
}

/** Replace what the mocked `client.from()` returns for subsequent calls. */
export function setFromResult(client: SupabaseClient, builder: object): void {
	(client.from as unknown as Mock).mockReturnValue(builder);
}

/**
 * Build a chainable Supabase client mock with a single shared query stub.
 *
 * `single()` and the thenable `then()` both read the stub's live `data` / `error`
 * (so a test sets `getMockQuery(client, table).data = …` once); `single()` also unwraps
 * a non-empty array to its first element, mirroring PostgREST's single-row semantics.
 */
export function createMockSupabaseClient(): SupabaseClient {
	const mockQuery = {
		data: null as unknown,
		error: null as { message: string; code?: string } | null,
		select: vi.fn().mockReturnThis(),
		eq: vi.fn().mockReturnThis(),
		gte: vi.fn().mockReturnThis(),
		lte: vi.fn().mockReturnThis(),
		ilike: vi.fn().mockReturnThis(),
		in: vi.fn().mockReturnThis(),
		order: vi.fn().mockReturnThis(),
		returns: vi.fn().mockReturnThis(),
		insert: vi.fn().mockReturnThis(),
		update: vi.fn().mockReturnThis(),
		delete: vi.fn().mockReturnThis(),
		upsert: vi.fn().mockResolvedValue({ data: null, error: null }),
		single: vi.fn(function (this: MockQueryBuilder) {
			// PostgREST single-row: unwrap a non-empty array to its first element.
			if (Array.isArray(this.data) && this.data.length > 0) {
				return Promise.resolve({ data: this.data[0], error: this.error });
			}
			return Promise.resolve({ data: this.data, error: this.error });
		}),
		then: vi.fn(function (this: MockQueryBuilder, resolve: (value: unknown) => unknown) {
			// Make the query object awaitable for `const { data, error } = await from()...`.
			return resolve({ data: this.data, error: this.error });
		})
	};

	return {
		from: vi.fn().mockReturnValue(mockQuery),
		rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
		auth: {
			getUser: vi.fn().mockResolvedValue({ data: { user: { id: 'test-user-id' } }, error: null }),
			getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user-id' } } } })
		}
	} as unknown as SupabaseClient;
}

