/**
 * Create a new Grouping under an Area of Importance.
 *
 * The one hierarchy tier the seed can't anticipate: a family needing a Grouping
 * beyond the 13 defaults adds it here (the editor's "Add a Grouping" form), then
 * assigns categories into it. Importance attaches to the Grouping, so the area
 * is chosen at creation. Deleting Groupings isn't offered — an empty Grouping is
 * harmless, since the report suppresses zero-activity rows.
 */
async createGroup(
	familyId: string,
	name: string,
	importanceAreaId: string
): Promise<CategoryGroup> {
	if (!familyId) {
		throw new Error('Family ID is required');
	}
	if (!name || name.trim() === '') {
		throw new Error('Grouping name is required');
	}
	if (name.length > 100) {
		throw new Error('Grouping name must be 100 characters or less');
	}
	if (!importanceAreaId) {
		throw new Error('Importance area ID is required');
	}

	const { data, error } = await this.supabase
		.from('category_groups')
		.insert({
			family_id: familyId,
			name: name.trim(),
			importance_area_id: importanceAreaId
		})
		.select()
		.single();

	if (error) {
		if (error.code === '23505') {
			throw new Error('A grouping with this name already exists in this family');
		}
		throw new Error(error.message);
	}

	return data;
}

