		throw new Error('Group ID is required');
	}
	if (!name || name.trim() === '') {
		throw new Error('Grouping name is required');
	}
	if (name.length > 100) {
		throw new Error('Grouping name must be 100 characters or less');
	}

	const { error } = await this.supabase
		.from('category_groups')
		.update({ name: name.trim(), updated_at: new Date().toISOString() })
		.eq('id', groupId);

	if (error) {
		if (error.code === '23505') {
			throw new Error('A grouping with this name already exists in this family');
		}
		throw new Error(error.message);
	}
}

