	onCreateGroup,
	onRenameGroup
}: Props = $props();

// Presentational-only state: which Grouping is being renamed, and the pending
// text for the rename input and the "Add a Grouping" form.
let editingGroupId = $state<string | null>(null);
let editName = $state('');
let newGroupName = $state('');
let newGroupImportanceId = $state('');

function startRename(groupId: string, currentName: string) {
	editingGroupId = groupId;
	editName = currentName;
}

function cancelRename() {
	editingGroupId = null;
	editName = '';
}

function submitRename(groupId: string) {
	const name = editName.trim();
	if (!name) return;
	onRenameGroup(groupId, name);
	cancelRename();
}

function submitNewGroup() {
	const name = newGroupName.trim();
	if (!name || !newGroupImportanceId) return;
	onCreateGroup(name, newGroupImportanceId);
	newGroupName = '';
	newGroupImportanceId = '';
}

