import { describe, it, expect, vi } from 'vitest';
import { render } from 'vitest-browser-svelte';
import HierarchyEditor from './HierarchyEditor.svelte';
import { buildHierarchyTree } from '$lib/utils/hierarchyTree';
import type { Category } from '$lib/types/Category';
import type { CategoryGroup, ImportanceArea } from '$lib/types/Hierarchy';

/**
 * Render tests for the presentational <HierarchyEditor>. Tree shaping is
 * unit-tested in hierarchyTree.spec.ts; these prove the component renders the
 * unassigned bucket, the Importance sections, and — the interaction — emits
 * onAssignCategory / onMoveGroup with the right ids when a select changes.
 */

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 }
];
const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' }
];
function cat(id: string, name: string, group_id: string | null): Category {
	return { id, name, color: null, group_id };
}
const categories: Category[] = [
	cat('cat-groceries', 'Groceries', 'grp-everyday'),
	cat('cat-allowance', 'Allowance', 'grp-kids'),
	cat('cat-orphan', 'Mystery Spend', null)
];

function renderEditor(
	overrides: {
		onAssignCategory?: (categoryId: string, groupId: string | null) => void;
		onMoveGroup?: (groupId: string, importanceAreaId: string) => void;
	} = {}
) {
	return render(HierarchyEditor, {
		tree: buildHierarchyTree(importanceAreas, groups, categories),
		importanceAreas,
		saving: false,
		onAssignCategory: overrides.onAssignCategory ?? (() => {}),
		onMoveGroup: overrides.onMoveGroup ?? (() => {})
	});
}

describe('HierarchyEditor', () => {
	it('renders the unassigned bucket with a count and its category', async () => {
		const screen = renderEditor();
		const bucket = screen.baseElement.querySelector('[data-testid="unassigned"]');
		expect(bucket).not.toBeNull();
		expect(bucket?.textContent).toContain('Unassigned categories (1)');
		expect(bucket?.textContent).toContain('Mystery Spend');
	});

	it('renders an Importance section per area with its groupings', async () => {
		const screen = renderEditor();
		const text = screen.baseElement.textContent ?? '';
		expect(text).toContain('Essential');
		expect(text).toContain('Priorities');
		expect(text).toContain('Everyday');
		expect(text).toContain('Kids');
	});

	it('emits onAssignCategory with the group id when an unassigned category is assigned', async () => {
		const onAssignCategory = vi.fn();
		const screen = renderEditor({ onAssignCategory });

		const bucket = screen.baseElement.querySelector('[data-testid="unassigned"]');
		const select = bucket?.querySelector('select') as HTMLSelectElement;
		select.value = 'grp-everyday';
		select.dispatchEvent(new Event('change', { bubbles: true }));

		expect(onAssignCategory).toHaveBeenCalledWith('cat-orphan', 'grp-everyday');
	});

	it('emits onAssignCategory with null when a category is set back to Uncategorized', async () => {
		const onAssignCategory = vi.fn();
		const screen = renderEditor({ onAssignCategory });

		// The first non-bucket grouping select belongs to a categorized category.
		const selects = Array.from(
			screen.baseElement.querySelectorAll('select[aria-label="Grouping for this category"]')
		) as HTMLSelectElement[];
		// Groceries (in Everyday) is the first category select outside the amber bucket.
		const groceries = selects.find(
			(s) => s.value === 'grp-everyday' && !s.closest('[data-testid="unassigned"]')
		);
		expect(groceries).toBeDefined();
		groceries!.value = '';
		groceries!.dispatchEvent(new Event('change', { bubbles: true }));

		expect(onAssignCategory).toHaveBeenCalledWith('cat-groceries', null);
	});

	it('emits onMoveGroup when a grouping is moved to another Importance', async () => {
		const onMoveGroup = vi.fn();
		const screen = renderEditor({ onMoveGroup });

		// The grouping's Importance select has options that are Importance names.
		const importanceSelects = Array.from(screen.baseElement.querySelectorAll('select')).filter(
			(s) => Array.from(s.options).some((o) => o.textContent === 'Essential')
		) as HTMLSelectElement[];
		// The Kids grouping currently sits in Priorities; move it to Essential.
		const kidsSelect = importanceSelects.find((s) => s.value === 'imp-pri');
		expect(kidsSelect).toBeDefined();
		kidsSelect!.value = 'imp-ess';
		kidsSelect!.dispatchEvent(new Event('change', { bubbles: true }));

		expect(onMoveGroup).toHaveBeenCalledWith('grp-kids', 'imp-ess');
	});
});

